abstract class ProductRoot { abstract double resolution(); }
interface ExportCap { String export(); }
interface NamedCap { String name(); }
class OrthoCombined extends ProductRoot implements ExportCap, NamedCap {
    double resolution() { return 0.05; }
    public String export() { return "csv"; }
    public String name() { return "ortho"; }
}
public class AbstractPlusInterfacesDemo {
    public static void main(String[] args) { var o = new OrthoCombined(); System.out.println(o.name() + ":" + o.export() + ":" + o.resolution()); }
}
